from pathlib import Path
import json,shutil,re,html,fitz
from PIL import Image
root=Path(__file__).parent; out=root.parent; assets=out/'assets';assets.mkdir(exist_ok=True)
source=root/'upload'
files=json.loads((root/'asset-map.json').read_text()) if (root/'asset-map.json').exists() else {}
for p in (source.iterdir() if source.exists() else []):
 if p.name.startswith(('Screenshot from 2026-09-25','Screenshot from 2026-09-28')): continue # Layout reference images are not site content.
 if p.suffix.lower() not in ['.pdf','.png','.jpeg','.jpg']: continue
 slug=re.sub(r'[^a-z0-9]+','-',p.stem.lower()).strip('-')
 name=slug+p.suffix.lower();shutil.copy2(p,assets/name);files[p.name]='/assets/'+name
 if p.suffix.lower()=='.pdf':
  doc=fitz.open(p);doc[0].get_pixmap(matrix=fitz.Matrix(1.25,1.25)).save(str(assets/(slug+'-preview.jpg')))
 else:
  im=Image.open(p).convert('RGB');im.thumbnail((1600,1600));im.save(assets/(slug+'-web.jpg'),quality=87,optimize=True)
(root/'asset-map.json').write_text(json.dumps(files,indent=2))
def asset(name):return files[name]
def thumb(name):
 s=Path(files[name]);return str(s.with_name(s.stem+('-preview.jpg' if s.suffix=='.pdf' else '-web.jpg')))
def esc(s):return html.escape(str(s),quote=True)
