def ext(url,label,cls='text-link'):return f'<a class="{cls}" href="{esc(url)}" target="_blank" rel="noopener">{esc(label)} {arrow}</a>'
def doclink(name,label='View certificate'):return ext(asset(name),label)
def gallery(names,captions=None):
 captions=captions or [Path(n).stem.replace('_',' ') for n in names]
 return '<div class="gallery">'+''.join(f'<figure><a href="{asset(n)}" target="_blank" rel="noopener"><img src="{thumb(n)}" alt="{esc(c)}" loading="lazy"></a><figcaption>{esc(c)}</figcaption></figure>' for n,c in zip(names,captions))+'</div>'
def heading(kicker,title,desc=''):return f'<header class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1>'+ (f'<p class="intro">{desc}</p>' if desc else '')+'</header>'
def page(path,title,body,section=None):
 section=section or title; active=section.split('/')[0]; dest=out/path.strip('/')/'index.html' if path!='/' else out/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
 menu=''.join(f'<a href="{("/" if n=="Home" else "/"+n.lower()+"/")}"'+(' aria-current="page"' if n==active else '')+f'>{n}</a>' for n in nav)
 social=''.join(f'<a href="{esc(v)}"'+(' target="_blank" rel="noopener"' if not v.startswith('mailto') else '')+f' aria-label="{k}" title="{k}">{ {"LinkedIn":"in","Google Scholar":"<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m2 9 10-6 10 6-10 6zM6 12v6c4 3 8 3 12 0v-6\"/></svg>","ORCID":"iD","Email":"<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"1\"/><path d=\"m3 6 9 7 9-7\"/></svg>"}[k]}</a>' for k,v in links.items())
 text=re.sub('<[^>]+>',' ',body)
 search_url='/projects/#'+path.strip('/').split('/')[-1] if path.startswith('/projects/') and path!='/projects/' else path
 if path!='/projects/embedded-prototypes/': search.append({'title':title,'url':search_url,'text':html.unescape(re.sub(r'\s+',' ',text))})
 dest.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — Md. Basim Al Zabir Shammo</title><meta name="description" content="Research portfolio of Md. Basim Al Zabir Shammo. Robotics, physics-informed machine learning, sensor fusion, publications, and projects."><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='12' fill='%231b3530'/%3E%3Ctext x='32' y='43' text-anchor='middle' font-family='Arial' font-size='34' fill='white'%3EB%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="wordmark" href="/">Basim Al Zabir<span>Shammo</span></a><nav id="navigation" aria-label="Main navigation">{menu}</nav><div class="header-actions"><button id="search-open" class="icon-button" aria-label="Search this site"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></button><button id="menu-toggle" class="icon-button" aria-label="Open menu" aria-expanded="false" aria-controls="navigation"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18"/></svg></button></div></header><main id="main" class="{'home' if path=='/' else 'interior'}">{body}</main><footer><div class="footer-inner"><div><p class="eyebrow">CONTACT</p><a class="email" href="mailto:al.zabir.shammo@gmail.com">al.zabir.shammo@gmail.com</a></div><div class="social">{social}</div><p class="copyright">© 2026 · Md. Basim Al Zabir Shammo</p></div></footer><dialog id="search-dialog" aria-labelledby="search-title"><div class="dialog-head"><h2 id="search-title">Search the portfolio</h2><button class="icon-button" id="search-close" aria-label="Close search">×</button></div><label class="sr-only" for="search-input">Search pages, papers, and projects</label><input id="search-input" type="search" placeholder="Search pages, papers, and projects…"><p id="search-status" role="status">Type a topic, skill, or publication title.</p><div id="search-results"></div></dialog></body></html>''')

