paper_descriptions={
 'https://doi.org/10.1007/s12145-026-02142-6': 'Rapid damage evaluation supports post-disaster response. Our study demonstrates that a pre-trained Vision Transformer (ViT-B32) outperforms a standard CNN baseline, achieving 97.85% accuracy. Through self-attention mechanisms, the ViT model captures global spatial relationships to identify subtle damage in visually cluttered disaster zones. We generated attention heatmaps to pinpoint structural damage, providing an interpretable and actionable tool for disaster management workflows.',
 'https://link.springer.com/chapter/10.1007/978-3-032-15764-5_50': 'Our research evaluated ten machine learning models to help develop an automated diagnostic system for Hepatitis C. We demonstrated that ensemble-boosting algorithms deliver better performance, with our AdaBoost classifier achieving the best accuracy.',
 'https://ieeexplore.ieee.org/document/11491546': 'This research presents a noninvasive, smartphone-based physiological monitoring system. By processing photoplethysmographic (PPG) signals captured via a mobile camera and applying machine learning models, including SVMs and multivariate regression, our system estimates indicators such as blood pressure, SpO₂, stress levels, and cardiovascular risk.',
 'https://ieeexplore.ieee.org/document/11381639': 'This work highlights the potential of data science to improve pediatric care and provide clinicians with data-driven tools for mental health assessment. I would like to thank my co-authors for their dedication and collaborative efforts on this project.',
 'https://ieeexplore.ieee.org/document/10955913': 'This work was presented at the 2024 International Conference on Recent Progresses in Science, Engineering and Technology (ICRPSET), held in Rajshahi, Bangladesh. Our study focuses on developing a vehicle identification framework using the YOLOv8 model tailored for the roadways of Bangladesh. Using real-time traffic footage, we aimed to improve traffic flow, reduce congestion, and support smart city initiatives.'
}
def pubrow(p):
 year,kind,title,authors,venue,url,cert,screen=p
 index=pubs.index(p)
 slug=['damage-assessment','rfid-access','hepatitis-c','nightmare-prediction','ppg-stress','mobile-ppg','vehicle-detection'][index]
 lines=project_descriptions[slug] if slug=='rfid-access' else research_descriptions[slug]
 image_url='/assets/publications/'+slug+'.jpg' if slug in ['damage-assessment','hepatitis-c','nightmare-prediction','ppg-stress'] else thumb(screen or cert)
 image_full=image_url if slug in ['damage-assessment','hepatitis-c','nightmare-prediction','ppg-stress'] else asset(screen or cert)
 publisher='Springer' if 'Springer' in venue else 'IEEE'
 image_label=publisher+' publication page: '+title if screen or slug in ['damage-assessment','hepatitis-c','nightmare-prediction','ppg-stress'] else 'Presentation certificate: '+title
 chevron='<svg class="entry-chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg>'
 certificate=f'<div class="publication-supporting-link">{doclink(cert,"View presentation certificate")}</div>' if cert else ''
 route='/publications/' if index<4 else '/publications/page-2/'
 search.append({'title':title,'url':route+'#'+slug,'text':' '.join(lines)+' '+authors+' '+venue+' '+year})
 return f'<article class="project-row publication-row" id="{slug}"><a class="project-visual" href="{image_full}" target="_blank" rel="noopener" aria-label="Open image: {esc(title)}"><img src="{image_url}" alt="{esc(image_label)}" width="240" height="240" loading="lazy"></a><div class="publication-content"><details class="entry-details"><summary><h2><span>{esc(title)}</span>{chevron}</h2></summary><div class="entry-body">{description_paragraph(lines)}<p class="publication-authors">{esc(authors)}</p><p class="publication-venue">{esc(venue)} · {year} · {kind}</p>{certificate}</div></details><a class="publication-button" href="{esc(url)}" target="_blank" rel="noopener" aria-label="View publication: {esc(title)}">View publication</a></div></article>'
page('/publications/','Publications',heading('PAPERS & SCHOLARLY WORK','Publications')+pubnav('Published')+'<div class="project-list publication-list">'+''.join(pubrow(p) for p in pubs[:4])+'</div><nav class="pagination" aria-label="Published paper pages"><span>1–4 of 7 papers</span><span aria-current="page">01</span><a href="/publications/page-2/">02 →</a></nav>')
page('/publications/page-2/','Published papers — page 2',heading('PAPERS & SCHOLARLY WORK','Publications')+pubnav('Published')+'<div class="project-list publication-list">'+''.join(pubrow(p) for p in pubs[4:])+'</div><nav class="pagination" aria-label="Published paper pages"><span>5–7 of 7 papers</span><a href="/publications/">← 01</a><span aria-current="page">02</span></nav>','Publications')
